// Online games played by the port (worms.ts, as every client plays them), for the server module's test:
// the server's WormsGame must wait for the same decisions (worm, situation, step) and end with the same
// scores and tables. `javaFixtures` writes them as WormsFixtures.java
// (server/src/test/java/net/slop/freegames/games/worms/), regenerated by gen-java-fixtures.ts and kept up
// to date by fixtures.test.ts.
import { portMachine } from './scenario.ts';
import type { Decider } from '../src/worms.ts';
import { MOVES } from '../src/worms.ts';
import { Raster, seed32 } from '../src/raster.ts';

export interface FixtureSpec {
  name: string;
  seed: number;
  kinds: number[];
  /** 255: the computer's */
  owners: number[];
  /** tables of SAME worms (else INITMOVES's) */
  tables?: (number[] | null)[];
  /** worm → the step from which the computer chooses for it */
  takeovers?: Record<number, number>;
}

export interface Fixture extends FixtureSpec {
  /** every decision asked for: step, worm, situation, move (-1: the computer chose) */
  decisions: number[][];
  scores: number[];
  finalTables: number[][];
}

function newTable(): number[] {
  const t = new Array(64).fill(0xf1);
  t[0x3e] = 0; t[0x3d] = 1; t[0x3b] = 2; t[0x37] = 3; t[0x2f] = 4; t[0x3f] = 0xf3; t[0x1f] = 5;
  return t;
}

/** the move a scripted player chooses: the (step mod n)-th free path */
export function scriptedMove(step: number, situation: number): number {
  const free = [0, 1, 2, 3, 4, 5].filter((m) => !(situation & (1 << m)));
  return free[(step * 5 + 3) % free.length];
}

export async function playFixture(spec: FixtureSpec): Promise<Fixture> {
  const { m, g } = portMachine(spec.seed ^ 0x5a5a);
  const decisions: number[][] = [];
  let step = 0;
  let finished = false;
  g.online = {
    setup: {
      worms: spec.kinds.map((k, i) => ({
        kind: k,
        name: Uint8Array.from([0x53, 0x41, 0x4d, 0x45]),
        moves: Uint8Array.from(spec.tables?.[i] ?? newTable()),
      })),
      owners: spec.owners,
    },
    seed: spec.seed,
    seats: {
      decider: (worm, situation): Decider | 'ai' => {
        if (spec.owners[worm] === 255) return 'ai';
        const s = step++;
        const t = spec.takeovers?.[worm];
        if (t !== undefined && t <= s) {
          decisions.push([s, worm, situation, -1]);
          return 'ai';
        }
        const move = scriptedMove(s, situation);
        decisions.push([s, worm, situation, move]);
        return { local: false, send() {}, poll: () => move };
      },
    },
    begin: () => { step = 0; },
    done: () => { finished = true; },
  };
  let failed: unknown = null;
  void g.run().catch((e) => { failed = e; m.release(); });
  // speed 9: the moves come as fast as the program computes them
  m.keyDown(0x39);
  for (let f = 0; !finished && f < 400000; f++) {
    await m.frame();
    if (failed) throw failed;
  }
  m.stop();
  if (!finished) throw new Error(`${spec.name}: the game did not end`);
  return {
    ...spec,
    decisions,
    scores: [...g.wscr],
    finalTables: g.w.map((b) => [...b.subarray(MOVES, MOVES + 64)]),
  };
}

export const SPECS: FixtureSpec[] = [
  { name: 'fourPeople', seed: 0x1234567, kinds: [1, 1, 1, 1], owners: [0, 1, 2, 3] },
  { name: 'twoPeopleAndTheComputer', seed: 0x7a5c3, kinds: [1, 2, 1, 2], owners: [0, 255, 2, 255] },
  { name: 'onePersonAndWild', seed: 0x2468ace, kinds: [3, 1, 3, 3], owners: [255, 1, 255, 255] },
  { name: 'aPlayerLeaves', seed: 0x13579, kinds: [1, 1, 1, 0], owners: [0, 1, 2, 255], takeovers: { 1: 6 } },
];

/** a taught table for the SAME worm of the last spec: what fourPeople's worm 2 learned */
export function sameSpec(taught: number[]): FixtureSpec {
  return { name: 'aTaughtWorm', seed: 0xbeef, kinds: [4, 1, 0, 2], owners: [0, 1, 255, 255], tables: [taught, null, null, null] };
}

export async function allFixtures(): Promise<Fixture[]> {
  const out: Fixture[] = [];
  for (const s of SPECS) out.push(await playFixture(s));
  out.push(await playFixture(sameSpec(out[0].finalTables[2])));
  return out;
}

const arr = (a: number[]) => `{ ${a.join(', ')} }`;

export function javaFixtures(fs: Fixture[]): string {
  const lines: string[] = [];
  lines.push('package net.slop.freegames.games.worms;');
  lines.push('');
  lines.push('/**');
  lines.push(' * Online games as the port plays them (web/games/worms/test/fixtures.ts; regenerate with');
  lines.push(' * `node web/games/worms/test/gen-java-fixtures.ts`): the server\'s WormsGame must ask for the same');
  lines.push(' * decisions and end with the same scores and tables. Generated: do not edit.');
  lines.push(' */');
  lines.push('final class WormsFixtures {');
  lines.push('  private WormsFixtures() {}');
  lines.push('');
  lines.push('  record Fixture(String name, int seed, int[] kinds, int[] owners, int[][] tables, int[][] takeovers, int[][] decisions, int[] scores, int[][] finalTables) {}');
  lines.push('');
  const r = new Raster(1);
  lines.push(`  /** src/raster.ts: new Raster(1).d012() four times, and seed32(0x8000000012345678n) */`);
  lines.push(`  static final int[] RASTER_1 = ${arr([r.d012(), r.d012(), r.d012(), r.d012()])};`);
  lines.push(`  static final int SEED32 = ${seed32(0x8000000012345678n) | 0};`);
  lines.push('');
  lines.push('  static final Fixture[] ALL = {');
  for (const f of fs) {
    const tables = [0, 1, 2, 3].map((i) => (f.tables?.[i] ? arr(f.tables[i]!) : 'null'));
    const take = Object.entries(f.takeovers ?? {}).map(([w, s]) => arr([Number(w), s]));
    lines.push(`    new Fixture("${f.name}", ${f.seed}, new int[] ${arr(f.kinds)}, new int[] ${arr(f.owners)},`);
    lines.push(`        new int[][] { ${tables.join(', ')} },`);
    lines.push(`        new int[][] { ${take.join(', ')} },`);
    lines.push('        new int[][] {');
    for (let i = 0; i < f.decisions.length; i += 8) {
      lines.push(`          ${f.decisions.slice(i, i + 8).map(arr).join(', ')},`);
    }
    lines.push('        },');
    lines.push(`        new int[] ${arr(f.scores)},`);
    lines.push('        new int[][] {');
    for (const t of f.finalTables) lines.push(`          ${arr(t)},`);
    lines.push('        }),');
  }
  lines.push('  };');
  lines.push('}');
  return lines.join('\n') + '\n';
}
